@startuml

class Resident {
  + name : string
  + street_address : string
  + phone_number : string
  + email : string
}

class ScheduledPickup {
  + street_address : string
  + description : string
  + pickup_time : time
}

class Item {
  + description : string
  + dimensions : string
  + weight : float
  + category : string
}

class Vehicle {
  + storage_space : float
}

class Route {
  + day : date
}

class VolunteerDriver {
  + available_days : string[]
}

class DistributionCenter {
  + name : string
}

class H2SEmployee {
  + name : string
}

class FoodBank {
  + name : string
}

class Client {
  + home_address : string
  + needed_categories : string[]
}

class Article {
  + description : string
  + category : string
}

class Delivery {
  + delivery_time : time
}

Resident "1" -- "*" ScheduledPickup : schedules
ScheduledPickup "1" -- "*" Item : contains
Vehicle "1" -- "*" Route : assigned to
VolunteerDriver "1" -- "*" Route : drives
Route "1" -- "*" ScheduledPickup : includes
Route "1" -- "*" Delivery : includes
Vehicle "1" -- "*" Delivery : performs
VolunteerDriver "1" -- "*" Delivery : performs
DistributionCenter "1" -- "*" Article : receives
H2SEmployee "1" -- "*" Article : examines
Article "1" -- "1" DistributionCenter : stored at
Client "1" -- "*" Delivery : receives
Client "1" -- "1" DistributionCenter : served by
FoodBank "1" -- "*" Item : receives

@enduml

